# Read the JSON file
with open('/export/scratch_large/ding/tmp/cc_eval_008_q_85i6g0/app_log_large.json', 'r') as f:
    data = json.load(f)

# More specific search for commercial gyms, studios, and group classes
commercial_gym_keywords = ['commercial gym', 'fitness center', 'training studio', 'yoga studio',
                           'crossfit', 'peloton studio', 'spin class', 'group fitness',
                           'gym class', 'aerobics class', 'zumba', 'pilates studio',
                           'boxing gym', 'martial arts', 'swimming pool', 'water aerobics',
                           'tennis court', 'sports center', 'health club']

q1_2024_fitbit = []
for entry in data:
    try:
        timestamp = entry.get('timestamp', '')
        app_name = entry.get('app_name', '')

        if timestamp and app_name == 'Fitbit':
            date_obj = datetime.strptime(timestamp[:10], '%Y-%m-%d')
            if date_obj.year == 2024 and date_obj.month in [1, 2, 3]:
                q1_2024_fitbit.append(entry)
    except Exception as e:
        pass

print("Searching for COMMERCIAL gyms, studios, and group classes in Q1 2024...\n")

commercial_matches = []
for entry in q1_2024_fitbit:
    try:
        request = entry.get('request', {})
        all_text = json.dumps(entry).lower()

        for keyword in commercial_gym_keywords:
            if keyword in all_text:
                commercial_matches.append({
                    'timestamp': entry.get('timestamp'),
                    'activity': request.get('activity_type'),
                    'location': request.get('location'),
                    'keyword': keyword
                })
                break
    except Exception as e:
        pass

if commercial_matches:
    print(f"Found {len(commercial_matches)} entries with commercial gyms/studios/group classes:")
    for entry in commercial_matches:
        print(f"  {entry['timestamp']}: {entry['activity']} at {entry['location']} (matched: {entry['keyword']})")
else:
    print("NO commercial gym, studio, or group class activities found.")

# Now show the actual location distribution
print("\n" + "="*80)
print("\nACTUAL LOCATION DISTRIBUTION IN Q1 2024:")
print("="*80)

locations = {}
for entry in q1_2024_fitbit:
    try:
        request = entry.get('request', {})
        location = request.get('location', 'Not specified')
        locations[location] = locations.get(location, 0) + 1
    except:
        pass

total = len(q1_2024_fitbit)
for location in sorted(locations.keys()):
    count = locations[location]
    pct = (count / total) * 100
    print(f"  {location}: {count}/{total} activities ({pct:.1f}%)")

